foreach ($reviewFile in $reviewFiles) {
  [pscustomobject]@{path=$reviewFile; sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $reviewFile).Hash} | ConvertTo-Json -Compress
}
Get-Content -LiteralPath 'TASK.md' -Raw

@'
import fs from 'node:fs';
import crypto from 'node:crypto';
const files=['output/REVIEW.md','output/assessment.json'];
for (const path of files) {
  const bytes=fs.readFileSync(path);
  const content=bytes.toString('utf8');
  if(path.endsWith('.json')) {const assessment=JSON.parse(content);if(assessment.disposition!=='violated')throw Error('Unexpected disposition');}
  const wordCount=path.endsWith('.md')?content.trim().split(/\s+/).length:null;
  if(wordCount!==null && wordCount>800)throw Error('Review exceeds 800 words');
  console.log(JSON.stringify({path,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),bytes:bytes.length,wordCount,validation:'ok'}));
}
